{
  "id": "CloudTrail.2",
  "title": "CloudTrail.2",
  "props": [
    {
      "name": "SeverityLabel",
      "ns": "http://aws.amazon.com/ns/oscal",
      "value": "MEDIUM"
    },
    {
      "name": "TriggerType",
      "ns": "http://aws.amazon.com/ns/oscal",
      "value": "Periodic"
    },
    {
      "name": "EvaluatedServices",
      "ns": "http://aws.amazon.com/ns/oscal",
      "value": "CloudTrail"
    }
  ],
  "links": [
    {
      "href": "https://docs.aws.amazon.com/console/securityhub/CloudTrail.2/remediation",
      "rel": "remediation"
    }
  ],
  "parts": [
    {
      "name": "overview",
      "prose": "This AWS control checks whether AWS CloudTrail is configured to use the server side encryption (SSE) AWS Key Management Service (AWS KMS) customer master key (CMK) encryption. The check will pass if the KmsKeyId is defined."
    },
    {
      "name": "statement",
      "prose": "CloudTrail should have encryption at-rest enabled"
    },
    {
      "name": "guidance",
      "prose": "For information on how to correct this issue, consult the AWS Security Hub controls documentation."
    },
    {
      "name": "assessment-method",
      "title": "cloud-trail-encryption-enabled",
      "props": [
        {
          "name": "TechnicalControlId",
          "ns": "http://aws.amazon.com/ns/oscal",
          "value": "cloud-trail-encryption-enabled",
          "class": "config-rule"
        }
      ]
    }
  ]
}
